def print_table(all_results: dict[str, list[dict]], num_layers: int):
    header = f"{'Layer':>5}"
    for d in DIRECTIONS:
        header += f"  {d:>10}"
    print(header)
    print("-" * len(header))

    for layer in range(num_layers):
        row = f"{layer:>5}"
        for d in DIRECTIONS:
            if d in all_results:
                acc = all_results[d][layer]["accuracy"]
                row += f"  {acc:>10.4f}"
            else:
                row += f"  {'—':>10}"
        print(row)


